@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,500;0,600;0,700;1,500;1,600&display=swap');
:root{color-scheme:dark;--ink:#f4efe9;--muted:#a9a9b5;--line:rgba(255,255,255,.12);--panel:#171b28;--gold:#e4c890;--violet:#b8a4ed;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',system-ui,sans-serif}
*{box-sizing:border-box}html{min-width:320px;background:#101522}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 75% 4%,#323046 0%,#171c2b 40%,#101522 80%);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased}.shell{max-width:1440px;margin:auto;padding:0 6.1vw}.topbar{height:82px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.09);position:relative;z-index:2}.wordmark{font-size:12px;letter-spacing:.23em;font-weight:700;color:#f5f0e9;text-decoration:none}.brand-mark{color:var(--gold);font-size:17px;margin-right:10px}.top-actions{display:flex;gap:22px;align-items:center}.save-status{font-size:11px;color:#a6a7b3;letter-spacing:.04em}.icon-button{border:1px solid var(--line);border-radius:30px;background:rgba(255,255,255,.035);color:#e7e2e8;padding:9px 13px;font:500 11px var(--sans);cursor:pointer}.icon-button span{margin-left:5px}.game-frame{min-height:690px;margin:27px 0 0;position:relative;overflow:hidden;border:1px solid rgba(255,255,255,.11);border-radius:5px;background:#171c2a;box-shadow:0 28px 90px rgba(0,0,0,.26)}.scene-art{position:absolute;inset:0 0 auto;height:100%;overflow:hidden;background:linear-gradient(180deg,#201e31 0%,#42445c 36%,#84909b 61%,#344154 62%,#151b2a 100%)}.sky-glow{position:absolute;width:60%;height:65%;top:4%;left:18%;background:radial-gradient(ellipse,rgba(197,171,192,.27),transparent 66%);filter:blur(15px)}.moon{position:absolute;right:17%;top:10%;width:108px;aspect-ratio:1;border-radius:50%;background:radial-gradient(circle at 38% 36%,#fff5db,#e7d8cf 53%,#c9b9c9 100%);box-shadow:0 0 42px rgba(245,219,206,.3),0 0 130px rgba(228,185,196,.16)}.mountain{position:absolute;inset:auto 0 30%;height:51%;clip-path:polygon(0 61%,12% 25%,20% 44%,34% 8%,49% 57%,64% 18%,76% 50%,87% 22%,100% 58%,100% 100%,0 100%)}.mountain-back{background:linear-gradient(150deg,#717485,#41465b 70%);opacity:.65}.mountain-front{height:41%;bottom:27%;clip-path:polygon(0 67%,17% 32%,27% 58%,43% 13%,58% 54%,76% 20%,91% 61%,100% 40%,100% 100%,0 100%);background:linear-gradient(160deg,#565a70,#282e43)}.water{position:absolute;inset:61% 0 0;background:linear-gradient(180deg,#455061,#20283a 55%,#161d2e)}.reflection{position:absolute;right:13%;top:61%;height:35%;width:17%;background:linear-gradient(180deg,rgba(236,215,201,.24),transparent 84%);clip-path:polygon(32% 0,68% 0,100% 100%,0 100%);filter:blur(8px)}.shore{position:absolute;left:-5%;bottom:25%;width:55%;height:22%;background:linear-gradient(6deg,#181d2b 22%,#30354a 23%,#23283b 26%,transparent 27%);clip-path:polygon(0 35%,100% 0,86% 28%,18% 100%,0 100%)}.art-label{position:absolute;top:24px;right:30px;font-size:9px;letter-spacing:.18em;color:rgba(255,255,255,.6)}.art-dot,.eyebrow span{display:inline-block;width:6px;height:6px;border-radius:50%;background:#dfc58e;box-shadow:0 0 12px #dfc58e;margin-right:8px}.welcome-screen{min-height:690px;position:relative;z-index:1;display:flex;align-items:center;padding:65px 8.5%;background:linear-gradient(90deg,rgba(15,20,33,.98) 0%,rgba(15,20,33,.92) 39%,rgba(15,20,33,.45) 73%,rgba(15,20,33,.12) 100%)}.welcome-copy{position:relative;z-index:1;max-width:570px}.eyebrow{font-size:10px;letter-spacing:.19em;text-transform:uppercase;color:#d9cba9;margin-bottom:25px}.welcome-copy h1{font:500 clamp(54px,6.1vw,82px)/.99 var(--serif);letter-spacing:-.045em;margin:0 0 23px}.welcome-copy h1 em{color:#e4c890;font-weight:500}.welcome-deck{font-size:15px;line-height:1.75;color:#c3c0c9;max-width:455px;margin:0 0 24px}.welcome-meta{display:flex;gap:20px;flex-wrap:wrap;font-size:10px;letter-spacing:.04em;color:#c1bdc8;margin-bottom:32px}.primary-button{background:#e5cc98;color:#201d25;border:0;border-radius:3px;padding:14px 19px;font:700 12px var(--sans);letter-spacing:.025em;cursor:pointer;transition:transform .18s,background .18s;box-shadow:0 5px 20px rgba(0,0,0,.14)}.primary-button span{font-size:17px;vertical-align:-1px;margin-left:19px}.primary-button:hover{background:#f0dbaa;transform:translateY(-2px)}.tiny-note{font-size:10px;color:#898b9a;margin-top:18px}.continue-button{margin-left:12px;border:1px solid rgba(255,255,255,.25);border-radius:3px;background:rgba(255,255,255,.05);color:#f3eee7;padding:13px 15px;font:600 11px var(--sans);cursor:pointer}.welcome-orbit{position:absolute;right:12%;top:50%;transform:translateY(-50%);width:min(36vw,410px);aspect-ratio:1;border-radius:50%;border:1px solid rgba(234,217,199,.16);display:grid;place-items:center}.orbit-ring{position:absolute;border:1px solid rgba(234,217,199,.25);border-radius:50%;inset:11%;transform:rotate(-30deg) scaleX(.68)}.ring-two{inset:1%;transform:rotate(53deg) scaleX(.72);border-color:rgba(202,180,224,.24)}.orbit-star{font:84px var(--serif);color:rgba(234,211,172,.75);text-shadow:0 0 55px rgba(234,211,172,.42)}.orbit-caption{position:absolute;bottom:15%;right:-2%;font-size:9px;line-height:1.8;letter-spacing:.22em;color:#d4c6cc}.story-screen{position:relative;z-index:1;min-height:690px;background:linear-gradient(90deg,rgba(15,19,30,.43),rgba(17,21,34,.97) 28%,rgba(17,21,34,.99) 100%)}.story-layout{min-height:690px;display:grid;grid-template-columns:255px 1fr}.sidebar{padding:42px 25px 28px 29px;border-right:1px solid rgba(255,255,255,.1);background:rgba(13,17,28,.54);display:flex;flex-direction:column}.chapter-card{padding:5px 0 25px;border-bottom:1px solid var(--line)}.chapter-kicker{font-size:9px;letter-spacing:.2em;color:#e3c88e}.chapter-progress{margin:13px 0 10px;height:2px;background:rgba(255,255,255,.14)}.chapter-progress span{display:block;width:12%;height:100%;background:#e5c992;transition:width .3s}.chapter-small{font:500 12px var(--serif);letter-spacing:.08em;color:#e6e1de}.cast-card{padding:25px 0}.cast-title{font-size:9px;letter-spacing:.17em;color:#aaa9b5;margin-bottom:17px}.cast-title span{font-size:8px;color:#d7bf8e;border:1px solid rgba(215,191,142,.5);border-radius:9px;padding:2px 5px;margin-left:5px}.cast-list{display:grid;gap:13px}.cast-person{display:grid;grid-template-columns:36px 1fr;gap:10px;align-items:center;opacity:.62;transition:opacity .2s}.cast-person.active{opacity:1}.avatar{height:36px;width:36px;border-radius:50%;display:grid;place-items:center;font:17px var(--serif);color:#fff;border:1px solid rgba(255,255,255,.22)}.avatar.lyra{background:radial-gradient(circle at 35% 25%,#edbbad,#824d69 70%,#322943)}.avatar.vesper{background:radial-gradient(circle at 35% 25%,#c3a5db,#574d81 70%,#272841)}.avatar.mara{background:radial-gradient(circle at 35% 25%,#d1c18f,#59735f 70%,#29353b)}.person-name{font:500 13px var(--serif);color:#f3ece7}.person-role{display:block;margin-top:3px;font-size:9px;color:#aaa9b6}.text-button{align-self:flex-start;border:0;background:transparent;color:#aaa9b4;font:500 10px var(--sans);padding:10px 0;cursor:pointer}.text-button:hover{color:#f3d9a8}.sidebar .text-button{margin-top:auto}.narrative-panel{max-width:780px;padding:52px clamp(35px,7vw,100px) 25px;margin:auto;width:100%;align-self:stretch;display:flex;flex-direction:column}.scene-eyebrow{font-size:9px;letter-spacing:.2em;color:#d8bf8d;margin-bottom:12px}.scene-heading h2{font:500 clamp(32px,3vw,43px)/1.14 var(--serif);margin:0 0 22px;letter-spacing:-.02em;color:#f5f0e9}.narrative-copy{font:15px/1.82 var(--serif);color:#c8c4ce;max-width:660px;white-space:pre-line}.narrative-copy p{margin:0 0 13px}.narrative-copy strong{color:#f3dca9;font-weight:500}.quote-line{font:italic 16px/1.6 var(--serif);color:#e2c99a;border-left:1px solid #bca577;padding:2px 0 2px 15px;margin-top:17px}.choice-heading{font-size:9px;letter-spacing:.18em;color:#a6a6b0;margin:29px 0 12px}.choices{display:grid;gap:9px}.choice-button{display:flex;gap:14px;align-items:center;text-align:left;width:100%;background:rgba(255,255,255,.04);border:1px solid rgba(255,255,255,.12);border-radius:3px;padding:13px 15px;color:#e9e5e3;font:500 12px/1.45 var(--sans);cursor:pointer;transition:background .18s,border .18s,transform .18s}.choice-button:hover{transform:translateX(3px);background:rgba(222,198,150,.1);border-color:rgba(222,198,150,.58)}.choice-glyph{font-size:14px;color:#dfc58e;min-width:14px}.choice-button small{display:block;font:10px/1.45 var(--sans);color:#a9a8b2;margin-top:3px}.story-footer{display:flex;justify-content:space-between;align-items:center;border-top:1px solid rgba(255,255,255,.1);margin-top:auto;padding-top:16px;font-size:9px;letter-spacing:.07em;color:#777b8c}.story-footer b{color:#dec38c;margin-left:5px}.ending-actions{display:flex;align-items:center;gap:18px;margin-top:26px}.ending-actions .text-button{margin:0}.page-footer{height:54px;display:flex;justify-content:space-between;align-items:center;color:#767988;font-size:8px;letter-spacing:.19em}.page-footer i{font-style:normal;color:#d2b986;margin:0 6px}.hidden{display:none!important}.fade-in{animation:appear .38s ease both}@keyframes appear{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:850px){.shell{padding:0 18px}.topbar{height:66px}.save-status{display:none}.game-frame{margin-top:16px}.welcome-screen{padding:55px 7%;min-height:690px;background:linear-gradient(90deg,rgba(15,20,33,.97),rgba(15,20,33,.82) 62%,rgba(15,20,33,.55))}.welcome-orbit{right:4%;width:34vw;opacity:.56}.story-layout{grid-template-columns:190px 1fr}.sidebar{padding:32px 18px}.narrative-panel{padding:38px 30px 22px}.page-footer{font-size:7px;letter-spacing:.12em}}
@media(max-width:600px){.shell{padding:0 10px}.topbar{height:58px}.wordmark{font-size:10px}.icon-button{padding:8px 10px}.game-frame{margin-top:10px;min-height:calc(100dvh - 135px)}.scene-art{min-height:100%}.moon{width:78px;right:13%;top:9%}.art-label{font-size:7px;right:13px;top:15px}.welcome-screen{min-height:calc(100dvh - 135px);padding:45px 23px 34px;align-items:flex-end;background:linear-gradient(180deg,rgba(15,20,33,.3),rgba(15,20,33,.78) 28%,rgba(15,20,33,.98) 63%)}.welcome-copy h1{font-size:58px}.welcome-deck{font-size:14px;line-height:1.65}.welcome-meta{gap:10px 14px;font-size:9px}.welcome-orbit{top:23%;right:11%;width:42vw;transform:translateY(-20%);opacity:.45}.orbit-star{font-size:56px}.orbit-caption{font-size:7px}.tiny-note{font-size:9px}.continue-button{margin:9px 0 0}.story-screen{min-height:calc(100dvh - 135px);background:rgba(17,21,34,.93)}.story-layout{min-height:calc(100dvh - 135px);display:flex;flex-direction:column}.sidebar{padding:12px 17px 0;border-right:0;border-bottom:1px solid rgba(255,255,255,.1);background:rgba(13,17,28,.6);display:block}.chapter-card{padding:0 0 10px;border-bottom:0;display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:10px}.chapter-kicker{font-size:8px}.chapter-progress{margin:0}.chapter-small{font:9px var(--sans);letter-spacing:.07em;text-align:right}.cast-card{padding:2px 0 12px}.cast-title{display:none}.cast-list{display:flex;gap:8px}.cast-person{grid-template-columns:25px auto;gap:5px}.avatar{width:25px;height:25px;font-size:12px}.person-name{font-size:10px}.person-role{display:none}.sidebar>.text-button{position:absolute;right:16px;top:10px;padding:0;font-size:0}.sidebar>.text-button:after{content:'↺';font-size:15px}.narrative-panel{padding:27px 20px 17px;min-height:465px;flex:1}.scene-eyebrow{font-size:8px;margin-bottom:9px}.scene-heading h2{font-size:32px;margin-bottom:15px}.narrative-copy{font-size:14px;line-height:1.7}.quote-line{font-size:14px;margin-top:12px}.choice-heading{margin:20px 0 9px;font-size:8px}.choices{gap:7px}.choice-button{padding:12px;font-size:11px}.choice-button small{font-size:9px}.story-footer{font-size:8px;padding-top:12px;margin-top:23px}.ending-actions{margin-top:20px}.page-footer{height:43px;letter-spacing:.1em}.page-footer span:last-child{max-width:55%;text-align:right;line-height:1.6}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation-duration:.01ms!important;transition-duration:.01ms!important;scroll-behavior:auto!important}}

const $ = (id) => document.getElementById(id);
const cast = {
  lyra: { name: 'Lyra', role: 'Lighthouse keeper', initial: 'L', avatar: 'lyra', title: 'The light she keeps', quote: '“I want someone who sees me, not just the light I keep on.”',
    text: 'At the island’s edge, Lyra tends a lighthouse whose beam has been dark for a hundred years. Its flame is not broken; it is waiting for someone to decide what the island should become.\n\nShe admits the heart-tide made her feel certain she loved you. The feeling is still there—but she wants to know what remains when nobody is being pulled by magic.',
    choices: [ ['Help relight the beacon together.', 'You share the work, and she lets you see the hope beneath her bravado.', 1], ['Ask what she would do if the island were free.', 'For once, Lyra talks about the future she wants for herself.', 0] ],
    romance: ['Together, you tend the beacon—not as its keeper and guest, but as two people who chose to stay. When its new light reaches the mainland, Lyra takes your hand. The island is still strange; the choice to meet each sunrise together is entirely yours.', 'The beacon throws a silver path across the sea. Lyra chooses to sail beside you and find out what love feels like when it is freely given. At the rail, she threads her fingers through yours. Geyropoa fades behind you, but your story is only beginning.'],
    friend: 'You leave the beacon in Lyra’s capable hands and promise to write. She hugs you once, then turns back toward the light she chose for herself. It is not a romance, and it is not a lesser thing.' },
  vesper: { name: 'Vesper', role: 'Cartographer', initial: 'V', avatar: 'vesper', title: 'A map with no edges', quote: '“I’ve mapped every road here. I’ve never asked where I wanted to go.”',
    text: 'Vesper draws maps on scraps of black glass. Every road she charts curls back toward the island’s heart, where the old heart-tide began. She is fascinated by the pattern—and quietly afraid of what it means.\n\nShe tells you the magic made her fall for you at first sight. She does not want that spell to make your choice for either of you.',
    choices: [ ['Trace the impossible road with her.', 'You trust her curiosity, and she trusts you with the map she has hidden.', 1], ['Tell her you would rather get lost together.', 'Vesper laughs. For the first time, she lets the map stay unfinished.', 0] ],
    romance: ['The map ends at a blank place marked HERE. Vesper says she wants to discover the rest with you, one uncharted day at a time. You kiss beneath a sky she has not yet named, and the future feels wonderfully unmapped.', 'Vesper closes her atlas and chooses the open road with you. She takes your hand—not because the map says to, but because she wants to. Beyond Geyropoa, every direction is new.'],
    friend: 'Vesper gives you a small map with one road leading off the island. “For when you’re ready,” she says. You part with a real friendship, and no spell left to explain it.' },
  mara: { name: 'Mara', role: 'Keeper of the wilds', initial: 'M', avatar: 'mara', title: 'The garden at the world’s end', quote: '“If the tide goes quiet, I still want to hear what my own heart says.”',
    text: 'Mara lives among the moonlit gardens, where flowers turn their faces toward whoever is speaking. She knows the island’s heart-tide is fading, and has been saving seeds in case the magic—and the home she knows—disappears.\n\nShe tells you she is drawn to you, but wants her feelings to be hers. You both have a chance to find out what that means.',
    choices: [ ['Help Mara gather seeds for a new garden.', 'She shares the garden she hopes to grow beyond the island.', 1], ['Ask her to show you her favorite quiet place.', 'Mara leads you away from the enchanted blooms, somewhere she can simply be herself.', 0] ],
    romance: ['Mara plants the first seed in the soil beyond Geyropoa. She asks you to help her make a home there—not because fate arranged it, but because you make her feel safe enough to imagine one. You say yes, and she kisses you beneath an ordinary, beautiful dawn.', 'Mara chooses to travel with you and carry a pocketful of seeds toward whatever comes next. You promise to help her find a place to plant them. Her smile is soft, certain, and entirely her own.'],
    friend: 'You help Mara pack her seeds for the journey ahead. She will stay and tend the garden while you go, and you promise to return. You part as friends, with the island’s wildflowers waving you on.' }
};

const state = { screen: 'title', node: 'arrival', route: null, bond: 0, chapter: 1 };
const STORAGE_KEY = 'geyropoa-heart-tide-save-v1';
let audioContext = null;
let soundOn = false;

function save() {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch (_) {}
  $('saveStatus').textContent = state.screen === 'ending' ? 'Ending reached · Saved locally' : 'Progress saved locally';
}
function showTitle() {
  $('storyScreen').classList.add('hidden');
  $('welcomeScreen').classList.remove('hidden');
  const saved = readSave();
  $('continueButton').classList.toggle('hidden', !saved || saved.screen === 'title');
  $('saveStatus').textContent = saved && saved.screen !== 'title' ? 'A story is waiting for you' : 'A story about choosing';
}
function readSave() {
  try { const data = JSON.parse(localStorage.getItem(STORAGE_KEY)); return data && data.node ? data : null; } catch (_) { return null; }
}
function begin() {
  Object.assign(state, { screen: 'story', node: 'arrival', route: null, bond: 0, chapter: 1 });
  render();
}
function continueStory() {
  const saved = readSave();
  if (saved) Object.assign(state, saved);
  state.screen = 'story';
  render();
}
function openStory() {
  $('welcomeScreen').classList.add('hidden');
  $('storyScreen').classList.remove('hidden');
}
function setText(element, text) {
  element.textContent = text;
}
function renderCast() {
  $('castList').innerHTML = Object.entries(cast).map(([key, person]) => `<div class="cast-person ${state.route === key ? 'active' : ''}"><div class="avatar ${person.avatar}">${person.initial}</div><div><span class="person-name">${person.name}</span><span class="person-role">${person.role}</span></div></div>`).join('');
}
function makeChoice(label, detail, action, glyph = '✦') {
  const button = document.createElement('button');
  button.className = 'choice-button';
  button.innerHTML = `<span class="choice-glyph" aria-hidden="true">${glyph}</span><span>${label}${detail ? `<small>${detail}</small>` : ''}</span>`;
  button.addEventListener('click', action);
  return button;
}
function displayScene({ eyebrow = 'GEYROPOA · NIGHT', title, text, quote = '', choices = [], ending = false }) {
  openStory();
  $('sceneEyebrow').textContent = eyebrow;
  $('sceneTitle').textContent = title;
  $('sceneText').textContent = text;
  $('sceneQuote').textContent = quote;
  $('sceneQuote').classList.toggle('hidden', !quote);
  $('choiceHeading').classList.toggle('hidden', ending);
  $('choices').classList.toggle('hidden', ending);
  $('endingActions').classList.toggle('hidden', !ending);
  $('choices').replaceChildren();
  choices.forEach((choice) => $('choices').appendChild(makeChoice(...choice)));
  $('chapterKicker').textContent = ending ? 'THE END' : `CHAPTER 0${state.chapter}`;
  $('chapterSmall').textContent = ending ? 'YOUR STORY CONTINUES' : (state.node === 'arrival' ? 'THE STRANGE SHORE' : state.route ? `${cast[state.route].name.toUpperCase()}’S STORY` : 'THE HEART-TIDE');
  $('progressFill').style.width = ending ? '100%' : state.node === 'arrival' ? '16%' : state.node === 'truth' ? '66%' : state.node === 'commit' ? '78%' : '48%';
  $('footerHint').textContent = ending ? 'Thank you for visiting Geyropoa.' : 'Your choices shape the story.';
  renderCast();
  $('narrative-panel')?.classList.remove('fade-in');
  document.querySelector('.narrative-panel').classList.remove('fade-in');
  void document.querySelector('.narrative-panel').offsetWidth;
  document.querySelector('.narrative-panel').classList.add('fade-in');
  save();
}
function enterRoute(route) {
  state.route = route;
  state.node = 'route';
  state.chapter = 2;
  const person = cast[route];
  displayScene({ eyebrow: `${person.name.toUpperCase()} · THE ${person.role.toUpperCase()}`, title: person.title, text: person.text, quote: person.quote,
    choices: person.choices.map(([label, detail, points]) => [label, detail, () => { state.bond = points; state.node = 'commit'; state.chapter = 3; render(); }]) });
}
function ending(type) {
  state.node = 'ending';
  state.screen = 'ending';
  state.chapter = 4;
  if (type === 'truth') {
    displayScene({ eyebrow: 'GEYROPOA · FIRST LIGHT', title: 'A heart, set free', text: 'You walk to the island’s heart and speak the truth aloud: nobody owes love to a spell. The heart-tide breaks like a wave of warm light.\n\nLyra is free to tend her beacon for herself. Vesper can draw a map that leads anywhere. Mara can choose where to plant her seeds. They thank you—not as someone who rescued them, but as the first person who let them choose.\n\nAlone on the shore, you watch the sunrise and wonder what you might choose next.', ending: true });
    return;
  }
  const person = cast[state.route];
  let title, text;
  if (type === 'romance') {
    title = state.bond ? `A future with ${person.name}` : `A beginning with ${person.name}`;
    text = person.romance[state.bond ? 0 : 1];
  } else if (type === 'friend') {
    title = `A friendship with ${person.name}`;
    text = person.friend;
  } else {
    title = 'The road you take alone';
    text = `You thank ${person.name} for trusting you with the truth. You do not promise a romance you cannot give. She looks a little sad, then smiles with relief.\n\nThe three islanders watch you leave together as friends, free to write their own next chapters. You sail toward the mainland beneath a sky full of unfamiliar stars. Choosing honestly is its own kind of kindness.`;
  }
  displayScene({ eyebrow: `${person.name.toUpperCase()} · YOUR CHOICE`, title, text, ending: true });
}
function render() {
  state.screen = state.screen === 'ending' || state.node === 'ending' ? 'ending' : 'story';
  if (state.node === 'arrival') {
    state.screen = 'story';
    displayScene({ eyebrow: 'GEYROPOA · NIGHT', title: 'A shore without footprints', text: 'Your boat drifts into a cove beneath a violet moon. You are the only arrival Geyropoa has seen in years. Three young demon women wait on the beach, each with a different kind of wonder in her eyes.\n\nThey introduce themselves as Lyra, Vesper, and Mara. All three are adults, eighteen or older. Each confesses that the island’s old heart-tide has filled her with a sudden, impossible love for you.\n\nBut they do not ask you to believe a spell. They ask you to stay long enough to meet the people they are when the magic grows quiet.', quote: '“You get to choose,” Lyra says. “And so do we.”', choices: [
      ['Meet Lyra at the lighthouse.', 'A keeper who wants to decide what her light is for.', () => enterRoute('lyra')],
      ['Follow Vesper to her map room.', 'A cartographer looking for a road beyond the island.', () => enterRoute('vesper')],
      ['Walk with Mara through the moon garden.', 'A gardener making plans for a life of her own.', () => enterRoute('mara')],
      ['Ask about the heart-tide.', 'Find out how to break the spell before choosing anyone.', () => { state.node = 'truth'; state.chapter = 2; render(); }]
    ] });
  } else if (state.node === 'route' && state.route) {
    const person = cast[state.route];
    displayScene({ eyebrow: `${person.name.toUpperCase()} · THE ${person.role.toUpperCase()}`, title: person.title, text: person.text, quote: person.quote, choices: person.choices.map(([label, detail, points]) => [label, detail, () => { state.bond = points; state.node = 'commit'; state.chapter = 3; render(); }]) });
  } else if (state.node === 'commit' && state.route) {
    const person = cast[state.route];
    displayScene({ eyebrow: 'GEYROPOA · BEFORE DAWN', title: 'What will you choose?', text: `${person.name} stands with you at the edge of the shore. The heart-tide is fading. Soon, the island’s pull will be gone, and every feeling left here will belong to the person who feels it.\n\n${person.name} meets your eyes. “I care for you,” she says. “But I want your answer to be yours. What do you want our story to be?”`, quote: person.quote, choices: [
      ['Choose a romance together.', 'Be honest about the feelings you want to explore.', () => ending('romance')],
      ['Choose a lasting friendship.', 'Care for each other without becoming a couple.', () => ending('friend')],
      ['Set out alone.', 'Decline romance and leave room for everyone to choose freely.', () => ending('solo')]
    ] });
  } else if (state.node === 'truth') {
    state.screen = 'story';
    displayScene({ eyebrow: 'GEYROPOA · THE ISLAND’S HEART', title: 'The spell beneath the tide', text: 'At the island’s center, you find a pool of black water ringed with old runes. Vesper’s map fits the stones. The heart-tide is not a curse exactly—it magnifies longing until it feels like destiny.\n\nThe three women can break it, but only if someone speaks the thing the spell cannot understand: love is a choice, not a debt. You could say the words and leave all three free to discover what they truly feel.', quote: 'The tide stills. The island waits.', choices: [['Break the heart-tide.', 'Give every heart back to its owner.', () => ending('truth')]] });
  } else if (state.node === 'ending') {
    state.screen = 'ending';
    render();
  }
}

